#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

static void url_decode(const char *src, char *dst)
{
    while (*src) {
        if (*src == '+') {
            *dst++ = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            char hex[3] = { src[1], src[2], '\0' };
            *dst++ = (char)strtol(hex, NULL, 16);
            src += 3;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

int main(void)
{
    char line[0x800];
    if (!fgets(line, sizeof(line), stdin)) {
        puts("NO_INPUT");
        return 0;
    }
    /* Strip trailing newline and optional carriage return */
    size_t len = strlen(line);
    while (len && (line[len-1] == '\n' || line[len-1] == '\r')) {
        line[--len] = '\0';
    }

    char *token = strtok(line, "&");
    while (token) {
        char *eq = strchr(token, '=');
        char key[1024] = {0};
        char val[1024] = {0};
        if (eq) {
            *eq = '\0';
            url_decode(token, key);
            url_decode(eq + 1, val);
        } else {
            url_decode(token, key);
            val[0] = '\0';
        }
        printf("%s=%s\n", key, val);
        token = strtok(NULL, "&");
    }
    return 0;
}
